import{_ as a,o as t,c as i,an as s}from"./chunks/framework.Ctf_xftG.js";const u=JSON.parse('{"title":"OSCP · Fondamentaux d’Active Directory","description":"Domaine, authentification et droits de réplication Active Directory.","frontmatter":{"title":"OSCP · Fondamentaux d’Active Directory","description":"Domaine, authentification et droits de réplication Active Directory."},"headers":[],"relativePath":"oscp/ad-theorie.md","filePath":"oscp/ad-theorie.md"}'),r={name:"oscp/ad-theorie.md"};function n(l,e,o,d,h,c){return t(),i("div",null,e[0]||(e[0]=[s('<h1 id="fondamentaux-d-active-directory" tabindex="-1">Fondamentaux d’Active Directory <a class="header-anchor" href="#fondamentaux-d-active-directory" aria-label="Permalink to &quot;Fondamentaux d’Active Directory&quot;">​</a></h1><h2 id="domaine-et-controleur-de-domaine" tabindex="-1">Domaine et contrôleur de domaine <a class="header-anchor" href="#domaine-et-controleur-de-domaine" aria-label="Permalink to &quot;Domaine et contrôleur de domaine&quot;">​</a></h2><p>Un domaine regroupe des objets de l’annuaire, dont les comptes, les groupes et les ordinateurs. Un contrôleur de domaine héberge une copie de l’annuaire et fournit notamment les services LDAP et Kerberos.</p><h2 id="authentification" tabindex="-1">Authentification <a class="header-anchor" href="#authentification" aria-label="Permalink to &quot;Authentification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Terme</th><th>Rôle</th></tr></thead><tbody><tr><td>TGT</td><td>Ticket initial qui permet au client de demander un ticket pour un service.</td></tr><tr><td>TGS</td><td>Service Kerberos qui délivre les tickets de service.</td></tr><tr><td>Ticket de service</td><td>Ticket présenté au service demandé pour authentifier le client.</td></tr><tr><td>SPN</td><td>Nom qui associe une instance de service au compte sous lequel elle s’exécute.</td></tr><tr><td>NTLM</td><td>Famille de protocoles Windows utilisant notamment un échange de défi et de réponse.</td></tr></tbody></table><h2 id="indicateur-de-compte-et-droit-de-replication" tabindex="-1">Indicateur de compte et droit de réplication <a class="header-anchor" href="#indicateur-de-compte-et-droit-de-replication" aria-label="Permalink to &quot;Indicateur de compte et droit de réplication&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nom</th><th>Signification</th></tr></thead><tbody><tr><td><code>DONT_REQ_PREAUTH</code></td><td>Indicateur de <code>userAccountControl</code> qui dispense le compte de préauthentification Kerberos.</td></tr><tr><td><code>DS-Replication-Get-Changes</code></td><td>Droit étendu permettant de répliquer les modifications d’une partition de l’annuaire.</td></tr></tbody></table><p><a href="https://datatracker.ietf.org/doc/html/rfc4120" target="_blank" rel="noreferrer">Fonctionnement de Kerberos</a> · <a href="https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/useraccountcontrol-manipulate-account-properties" target="_blank" rel="noreferrer">Indicateurs de compte Microsoft</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/adschema/r-ds-replication-get-changes" target="_blank" rel="noreferrer">Droit de réplication Microsoft</a>.</p><h2 id="heure-linux" tabindex="-1">Vérifier l’horloge du poste Linux <a class="header-anchor" href="#heure-linux" aria-label="Permalink to &quot;Vérifier l’horloge du poste Linux {#heure-linux}&quot;">​</a></h2><p>Sur un poste Linux utilisant systemd, le service de gestion de l’heure doit être accessible.</p><h3 id="afficher-l-heure-et-le-fuseau-du-poste" tabindex="-1">Afficher l’heure et le fuseau du poste <a class="header-anchor" href="#afficher-l-heure-et-le-fuseau-du-poste" aria-label="Permalink to &quot;Afficher l’heure et le fuseau du poste&quot;">​</a></h3><p>Lis l’heure locale, le fuseau et l’état de la synchronisation affichés par systemd.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> status</span></span></code></pre></div><h3 id="lire-les-proprietes-de-synchronisation" tabindex="-1">Lire les propriétés de synchronisation <a class="header-anchor" href="#lire-les-proprietes-de-synchronisation" aria-label="Permalink to &quot;Lire les propriétés de synchronisation&quot;">​</a></h3><p><code>NTPSynchronized</code> indique si l’horloge est synchronisée et <code>TimeUSec</code> donne l’heure du système.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> show</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> NTPSynchronized</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> TimeUSec</span></span></code></pre></div><p><a href="https://www.freedesktop.org/software/systemd/man/latest/timedatectl.html" target="_blank" rel="noreferrer">Manuel de timedatectl</a> · <a href="https://www.freedesktop.org/software/systemd/man/latest/org.freedesktop.timedate1.html" target="_blank" rel="noreferrer">Propriétés de timedate1</a>.</p><h2 id="time-synchronization-clock-skew" tabindex="-1">Time Synchronization &amp; Clock Skew <a class="header-anchor" href="#time-synchronization-clock-skew" aria-label="Permalink to &quot;Time Synchronization &amp; Clock Skew&quot;">​</a></h2><p>Kerberos vérifie la cohérence des horodatages. La tolérance habituelle est de 5 minutes, selon la politique du domaine. Un décalage excessif peut provoquer l’erreur <code>KRB_AP_ERR_SKEW</code> (Clock skew too great).</p><h3 id="afficher-l-heure-utc" tabindex="-1">Afficher l’heure UTC <a class="header-anchor" href="#afficher-l-heure-utc" aria-label="Permalink to &quot;Afficher l’heure UTC&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">date</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -u</span></span></code></pre></div><p>Affiche l’heure UTC du poste pour comparer les horloges sans confusion liée au fuseau horaire.</p><h3 id="verifier-le-decalage-ntp" tabindex="-1">Vérifier le décalage NTP <a class="header-anchor" href="#verifier-le-decalage-ntp" aria-label="Permalink to &quot;Vérifier le décalage NTP&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">ntpdate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> ntp.example.org</span></span></code></pre></div><p>Interroge un serveur NTP autorisé et affiche le décalage sans modifier l’horloge locale. Remplace le nom d’exemple par celui de ton serveur de temps.</p><h3 id="activer-la-synchronisation-de-l-heure" tabindex="-1">Activer la synchronisation de l’heure <a class="header-anchor" href="#activer-la-synchronisation-de-l-heure" aria-label="Permalink to &quot;Activer la synchronisation de l’heure&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> set-ntp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> true</span></span></code></pre></div><p>Active la synchronisation automatique sur un poste Linux compatible systemd disposant d’un service NTP configuré.</p><h3 id="installer-faketime" tabindex="-1">Installer faketime <a class="header-anchor" href="#installer-faketime" aria-label="Permalink to &quot;Installer faketime&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> faketime</span></span></code></pre></div><p>Installe faketime sur Debian et les distributions compatibles.</p><h3 id="simuler-une-date-et-une-heure" tabindex="-1">Simuler une date et une heure <a class="header-anchor" href="#simuler-une-date-et-une-heure" aria-label="Permalink to &quot;Simuler une date et une heure&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">faketime</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> &#39;2026-11-25 09:30:00&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> date</span></span></code></pre></div><p>Simule une date pour la commande <code>date</code>, sans modifier l’horloge du système. Utile pour les tests de comportement temporel dans un environnement de laboratoire.</p><h3 id="simuler-un-decalage-horaire" tabindex="-1">Simuler un décalage horaire <a class="header-anchor" href="#simuler-un-decalage-horaire" aria-label="Permalink to &quot;Simuler un décalage horaire&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">faketime</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> &#39;+2h&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> date</span></span></code></pre></div><p>Simule un décalage de deux heures pour ce processus uniquement.</p><h3 id="verifier-que-l-heure-reelle-est-inchangee" tabindex="-1">Vérifier que l’heure réelle est inchangée <a class="header-anchor" href="#verifier-que-l-heure-reelle-est-inchangee" aria-label="Permalink to &quot;Vérifier que l’heure réelle est inchangée&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">date</span></span></code></pre></div><p>Affiche de nouveau l’heure réelle du système après le test. Faketime ne remplace pas la synchronisation NTP et ne fonctionne pas avec tous les programmes.</p><p><a href="https://learn.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/maximum-tolerance-for-computer-clock-synchronization" target="_blank" rel="noreferrer">Politique Kerberos Microsoft</a> · <a href="https://manpages.debian.org/trixie/faketime/faketime.1.en.html" target="_blank" rel="noreferrer">Manuel faketime</a> · <a href="https://manpages.debian.org/trixie/ntpsec-ntpdate/ntpdate.8.en.html" target="_blank" rel="noreferrer">Manuel ntpdate</a>.</p><h2 id="fiches-associees" tabindex="-1">Fiches associées <a class="header-anchor" href="#fiches-associees" aria-label="Permalink to &quot;Fiches associées&quot;">​</a></h2><ul><li><a href="./ad-enumeration">Énumération Active Directory</a></li><li><a href="./ad-techniques">Techniques Active Directory</a></li><li><a href="./ad-lateral">Mouvement latéral</a></li></ul><p>Source d’origine : <a href="https://www.emmanuelsolis.com/oscp.html" target="_blank" rel="noreferrer">guide d’Emmanuel Solis</a>.</p>',44)]))}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
